mapper.select:
SELECT s.id, s.task_id, s.standard_id, s.standard_version_id, s.standard_name,
       s.version_no, s.filename, s.content_type, s.size_bytes, s.content_hash,
       s.storage_path, s.source_project_id, s.created_at
FROM task_code_standard s
JOIN task t ON t.id = s.task_id
JOIN project p ON p.id = t.project_id
WHERE s.id = #{id}
  AND t.deleted = 0
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
